"""Tests for `gate.py changes-schema` -- replaces the prose-fallback half of
audit finding #1 (inline duplicate CHANGES_SCHEMA copies in proofread.js /
write-sections.js, free to drift from the on-disk contract). Design spec:
docs/audits/2026-09-04-determinism-audit.md, sections 3.1, 5.

Validates against the canonical on-disk
src/skills/proofread/references/changes-schema.json using `jsonschema`
(Draft 2020-12), read fresh every run -- never an inline copy.

Most tests here invoke gate.py as a real subprocess (matching
tests/test_proofread_scripts.py's convention). The one exception is
`test_missing_jsonschema_package_exits_two`, which needs to simulate the
`jsonschema` package being unimportable -- that can't be done to a fresh
subprocess without manipulating its environment in a way that would be
its own source of flakiness, so it calls gate.py's own
`cmd_changes_schema()` in-process with `jsonschema` hidden from
`sys.modules`. This does not violate TST-09 (no ambient-binary-on-PATH
skip): it isn't skipping anything, it's exercising the ImportError branch
directly and asserting exit 2.
"""

import argparse
import copy
import importlib.util
import json
import os
import subprocess
import sys
import tempfile
import unittest
from unittest import mock

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
GATE = os.path.join(ROOT_DIR, "src", "scripts", "gate.py")
VALID_CHANGES_PATH = os.path.join(ROOT_DIR, "tests", "fixtures", "gate", "changes-valid.json")
SCHEMA_PATH = os.path.join(
    ROOT_DIR, "src", "skills", "proofread", "references", "changes-schema.json"
)


def run_gate(*args):
    """Invoke gate.py as a real subprocess. Auto-injects a scratch
    --ledger into a throwaway tempdir when the caller didn't supply one --
    without this, gate.py resolves the ledger via $CLAUDE_PROJECT_DIR (or
    cwd) and would write into any REAL .academic-helper/session-state.json
    that happens to exist there (TST-09 spirit: no ambient-environment
    dependency, including this one).
    """
    if "--ledger" not in args and args:
        with tempfile.TemporaryDirectory() as ledger_dir:
            return subprocess.run(
                [sys.executable, GATE, *args, "--ledger", os.path.join(ledger_dir, "session-state.json")],
                capture_output=True,
                text=True,
                timeout=30,
            )
    return subprocess.run(
        [sys.executable, GATE, *args],
        capture_output=True,
        text=True,
        timeout=30,
    )


def load_valid_changes():
    with open(VALID_CHANGES_PATH, encoding="utf-8") as fh:
        return json.load(fh)


def run_on_changes(payload):
    with tempfile.TemporaryDirectory() as tmpdir:
        path = os.path.join(tmpdir, "changes.json")
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, ensure_ascii=False)
        return run_gate("changes-schema", path, "--json")


class TestValidChangesPass(unittest.TestCase):
    def test_valid_fixture_passes(self):
        proc = run_gate("changes-schema", VALID_CHANGES_PATH, "--json")
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "pass")
        self.assertEqual(payload["violations"], [])


class TestMissingRationale(unittest.TestCase):
    def test_change_missing_rationale_fails(self):
        """Plant the exact mutation from the acceptance spec: a change
        object missing `rationale`.
        """
        payload = copy.deepcopy(load_valid_changes())
        del payload["changes"][0]["rationale"]
        proc = run_on_changes(payload)
        self.assertEqual(proc.returncode, 1, proc.stdout + proc.stderr)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "fail")
        self.assertTrue(len(result["violations"]) >= 1)
        violation = result["violations"][0]
        self.assertEqual(violation["check"], "schema")
        self.assertIn("path", violation)
        self.assertIn("rationale", violation["detail"])

    def test_violation_reports_json_path(self):
        payload = copy.deepcopy(load_valid_changes())
        payload["changes"].append(copy.deepcopy(payload["changes"][0]))
        del payload["changes"][1]["rationale"]
        proc = run_on_changes(payload)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        result = json.loads(proc.stdout)
        paths = [v["path"] for v in result["violations"]]
        self.assertTrue(any("changes" in p and "1" in p for p in paths), paths)


class TestOtherSchemaViolations(unittest.TestCase):
    def test_unknown_type_enum_value_fails(self):
        payload = copy.deepcopy(load_valid_changes())
        payload["changes"][0]["type"] = "not-a-real-type"
        proc = run_on_changes(payload)
        self.assertEqual(proc.returncode, 1, proc.stdout)

    def test_line_below_minimum_fails(self):
        payload = copy.deepcopy(load_valid_changes())
        payload["changes"][0]["line"] = 0
        proc = run_on_changes(payload)
        self.assertEqual(proc.returncode, 1, proc.stdout)

    def test_missing_required_top_level_stage_fails(self):
        payload = copy.deepcopy(load_valid_changes())
        del payload["stage"]
        proc = run_on_changes(payload)
        self.assertEqual(proc.returncode, 1, proc.stdout)

    def test_bare_array_of_changes_is_rejected_by_the_schema(self):
        """The canonical schema requires the wrapping {"stage", "changes"}
        object -- a bare array is a schema violation here (unlike
        citation-guard.py, which tolerates both shapes for a different
        purpose).
        """
        payload = copy.deepcopy(load_valid_changes())["changes"]
        proc = run_on_changes(payload)
        self.assertEqual(proc.returncode, 1, proc.stdout)


class TestMalformedInput(unittest.TestCase):
    def test_unparseable_json_exits_two(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = os.path.join(tmpdir, "changes.json")
            with open(path, "w", encoding="utf-8") as fh:
                fh.write("{ not json")
            proc = run_gate("changes-schema", path, "--json")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "error")

    def test_missing_file_exits_two(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            proc = run_gate(
                "changes-schema", os.path.join(tmpdir, "nope.json"), "--json"
            )
        self.assertEqual(proc.returncode, 2, proc.stdout)


class TestSchemaDriftGuard(unittest.TestCase):
    def test_canonical_schema_file_exists_and_is_read_fresh(self):
        """gate.py must read the canonical schema off disk, not carry its
        own inline copy -- prove the file this gate depends on actually
        exists at the path the module docstring names.
        """
        self.assertTrue(os.path.isfile(SCHEMA_PATH), SCHEMA_PATH)
        with open(SCHEMA_PATH, encoding="utf-8") as fh:
            schema = json.load(fh)
        self.assertEqual(schema.get("required"), ["stage", "changes"])


class TestMissingJsonschemaDependency(unittest.TestCase):
    def test_missing_jsonschema_package_exits_two(self):
        spec = importlib.util.spec_from_file_location("gate_under_test", GATE)
        gate_module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(gate_module)

        args = argparse.Namespace(changes=VALID_CHANGES_PATH)

        real_import = __import__

        def blocking_import(name, *a, **kw):
            if name == "jsonschema" or name.startswith("jsonschema."):
                raise ImportError("simulated: jsonschema not installed")
            return real_import(name, *a, **kw)

        with mock.patch("builtins.__import__", side_effect=blocking_import):
            exit_code, result = gate_module.cmd_changes_schema(args)

        self.assertEqual(exit_code, 2)
        self.assertEqual(result["status"], "error")
        self.assertIn("jsonschema", result["detail"])


if __name__ == "__main__":
    unittest.main()
